mapper.select:
SELECT



ORDER BY s.expense_date DESC, s.settlement_id DESC

    LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO settlement (
    application_id, item_code, expense_date, vendor_name, supply_amount, vat_amount, total_amount, description, receipt_file_id, status, created_by
) VALUES (
    #{applicationId}, #{itemCode}, #{expenseDate}, #{vendorName}, #{supplyAmount}, #{vatAmount}, #{totalAmount}, #{description}, #{receiptFileId}, #{status}, #{audit.userId}
)

mapper.select:
SELECT h.history_id, h.settlement_id, h.action_code, h.total_amount, h.memo, h.actor_id, u.user_name AS actor_name, h.acted_at FROM settlement_history h LEFT JOIN users u ON h.actor_id = u.user_id WHERE h.settlement_id IN
#{id}
ORDER BY h.settlement_id, h.acted_at, h.history_id
